def replace_in_file(filepath):
    with open(filepath, "r", encoding="utf-8") as f:
        content = f.read()

    # 1. Replace Emojis
    for emoji, svg in svgs.items():
        content = content.replace(emoji, svg)

    # 2. Replace CTA Navbar
    # Old CTA might look like:
    # <a href="https://wa.me/6289508029834..." ... class="bg-brand-navy ... Hubungi Kami</a>
    
    # Regex to find the CTA button in the navbar (inside <div class="hidden lg:block ml-2">)
    cta_pattern = re.compile(
        r"(<div class=\"hidden lg:block ml-2\">\s*)<a href=\"([^\"]+)\" target=\"_blank\" class=\"bg-brand-navy([^\"]*)\">Hubungi Kami</a>",
        re.DOTALL
    )
    
    def cta_replacer(match):
        prefix = match.group(1)
        href = match.group(2)
        old_classes = match.group(3)
        # We need to replace hover:bg-brand-blue with hover:bg-[#25D366] and hover:shadow-[...]
        new_classes = old_classes.replace("hover:bg-brand-blue", "hover:bg-[#25D366]")
        new_classes = re.sub(r"hover:shadow-\[[^\]]+\]", "hover:shadow-[0_4px_20px_rgba(37,211,102,0.4)]", new_classes)
        
        return (f'{prefix}<a href="{href}" target="_blank" class="group flex items-center bg-brand-navy{new_classes}">\n'
                f'                <span>Hubungi Kami</span>\n'
                f'                <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="currentColor" class="w-0 opacity-0 overflow-hidden group-hover:w-5 group-hover:opacity-100 group-hover:ml-2 transition-all duration-300 ease-in-out">\n'
                f'                    <path d="M17.472 14.382c-.297-.149-1.758-.867-2.03-.967-.273-.099-.471-.148-.67.15-.197.297-.767.966-.94 1.164-.173.199-.347.223-.644.075-.297-.15-1.255-.463-2.39-1.475-.883-.788-1.48-1.761-1.653-2.059-.173-.297-.018-.458.13-.606.134-.133.298-.347.446-.52.149-.174.198-.298.298-.497.099-.198.05-.371-.025-.52-.075-.149-.669-1.612-.916-2.207-.242-.579-.487-.5-.669-.51-.173-.008-.371-.01-.57-.01-.198 0-.52.074-.792.372-.272.297-1.04 1.016-1.04 2.479 0 1.462 1.065 2.875 1.213 3.074.149.198 2.096 3.2 5.077 4.487.709.306 1.262.489 1.694.625.712.227 1.36.195 1.871.118.571-.085 1.758-.719 2.006-1.413.248-.694.248-1.289.173-1.413-.074-.124-.272-.198-.57-.347m-5.421 7.403h-.004a9.87 9.87 0 01-5.031-1.378l-.361-.214-3.741.982.998-3.648-.235-.374a9.86 9.86 0 01-1.51-5.26c.001-5.45 4.436-9.884 9.888-9.884 2.64 0 5.122 1.03 6.988 2.898a9.825 9.825 0 012.893 6.994c-.003 5.45-4.437 9.884-9.885 9.884m8.413-18.297A11.815 11.815 0 0012.05 0C5.495 0 .16 5.335.157 11.892c0 2.096.547 4.142 1.588 5.945L.057 24l6.305-1.654a11.882 11.882 0 005.683 1.448h.005c6.554 0 11.89-5.335 11.893-11.893a11.821 11.821 0 00-3.48-8.413z"/>\n'
                f'                </svg>\n'
                f'            </a>')

    content = cta_pattern.sub(cta_replacer, content)

    with open(filepath, "w", encoding="utf-8") as f:
        f.write(content)

html_files = [
    "index.html", "layanan.html", "artikel.html", "baca-artikel.html", 
    "kontak.html", "lowongan.html", "tentang-kami.html", "testimoni.html"
]

for file in html_files:
    if os.path.exists(file):
        replace_in_file(file)
        print(f"Updated {file}")

print("Done.")
